from __future__ import annotations

import html
import json

from .literature_graph import neighborhood


def render_graph_html(
    graph: dict, origin: dict, limit: int = 40, full_graph: bool = False
) -> str:
    selected = {node["id"] for node in graph["nodes"]} if full_graph else {origin["id"]}
    if not full_graph:
        selected.update(node["id"] for _, node in neighborhood(graph, origin["id"], limit))
    data = {
        "origin": origin["id"],
        "nodes": [node for node in graph["nodes"] if node["id"] in selected],
        "edges": [
            edge
            for edge in graph["edges"]
            if edge["source"] in selected and edge["target"] in selected
        ],
        "updated": graph.get("citations_updated_at"),
    }
    payload = json.dumps(data, separators=(",", ":")).replace("</", "<\\/")
    return (
        r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Jarvis Literature Graph — __TITLE__</title>
<style>
:root{color-scheme:dark;--bg:#07101d;--panel:#0d1929e8;--line:#25364d;--text:#eaf2ff;--muted:#8fa4bf;--accent:#77e0c2;--cite:#ffac62;--couple:#55bde8;--similar:#65758d;--work:#d583ff;--r:14px;--shadow:0 18px 50px #0008;font:14px/1.45 Inter,ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:radial-gradient(circle at 45% 40%,#132944 0,#07101d 62%);color:var(--text)}button,input,select{font:inherit;color:inherit}.top{position:fixed;z-index:3;inset:18px 378px auto 20px;display:flex;gap:12px;align-items:flex-start;pointer-events:none}.brand,.controls,.panel,.key,.hint{background:var(--panel);border:1px solid #263954;border-radius:var(--r);box-shadow:var(--shadow);backdrop-filter:blur(16px);pointer-events:auto}.brand{padding:12px 16px;white-space:nowrap}.brand b{display:block;letter-spacing:.12em;text-transform:uppercase}.brand span,.sub,.meta{color:var(--muted);font-size:12px}.controls{display:flex;flex-wrap:wrap;gap:8px;padding:8px;min-width:260px;flex:1}.controls input,.controls select{min-width:120px;flex:1;border:0;outline:0;background:#07111f;border-radius:9px;padding:8px 11px}.controls select{max-width:230px}.controls button,.related button{border:1px solid #30445f;background:#14243a;border-radius:9px;padding:7px 10px;cursor:pointer;transition:.15s}.controls button:hover,.controls button:focus-visible,.related button:hover,.related button:focus-visible,.controls input:focus-visible,.controls select:focus-visible{border-color:var(--accent);outline:2px solid #77e0c244;transform:translateY(-1px)}canvas{display:block;width:100vw;height:100vh;touch-action:none}.panel{position:fixed;z-index:4;inset:18px 18px 18px auto;width:342px;padding:20px;overflow:auto}.panel h1{margin:3px 0 8px;font-size:clamp(18px,2vw,25px);line-height:1.18}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:15px 0}.chip{padding:4px 8px;border:1px solid #31455f;border-radius:99px;background:#0c1a2b;color:#bcd0e9;font-size:11px;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:14px 0}.metric{padding:9px;background:#081322;border-radius:10px;text-align:center}.metric b{display:block;font-size:17px}.source{display:inline-flex;color:var(--accent);text-decoration:none;margin:5px 0 14px}.source:hover{text-decoration:underline}.related{display:grid;gap:7px}.related button{text-align:left;padding:9px}.related small{display:block;color:var(--muted);margin-top:3px}.key{position:fixed;z-index:3;left:20px;bottom:20px;padding:11px 13px;display:flex;flex-wrap:wrap;gap:12px}.key label{display:flex;gap:6px;align-items:center;cursor:pointer}.key i{width:18px;height:3px;border-radius:4px;background:var(--c)}.hint{position:fixed;left:50%;bottom:20px;transform:translateX(-50%);padding:8px 12px;color:var(--muted);font-size:12px}.empty{color:var(--muted);margin-top:22px}@media(max-width:820px){.top{inset:10px 10px auto}.brand{display:none}.controls select{max-width:none}.panel{inset:auto 10px 10px;width:auto;max-height:42vh}.key{left:10px;bottom:auto;top:112px;max-width:calc(100vw - 20px)}.hint{display:none}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
.hint{bottom:72px}
</style></head><body>
<header class="top"><div class="brand"><b>Jarvis Atlas</b><span id="count"></span></div><div class="controls"><label hidden for="search">Search works</label><input id="search" placeholder="Search papers or manuscripts…" autocomplete="off"><label hidden for="focus">Focus work</label><select id="focus"><option value="">Choose a work…</option></select><label hidden for="tag">Filter by tag</label><select id="tag"><option value="">All tags</option></select><button id="fit" type="button">Fit</button><button id="reset" type="button">Reset</button><button id="reload" type="button">Reload</button></div></header>
<main><canvas id="graph" role="img" aria-label="Interactive literature relationship graph"></canvas><aside class="panel" id="panel" aria-live="polite"></aside></main>
<fieldset class="key" aria-label="Visible relationships"><label style="--c:var(--cite)"><input type="checkbox" value="cites" checked><i></i>Cites</label><label style="--c:var(--couple)"><input type="checkbox" value="bibliographic_coupling" checked><i></i>Shared references</label><label style="--c:var(--similar)"><input type="checkbox" value="similar" checked><i></i>Topic similarity</label><label style="--c:var(--work)"><input type="checkbox" value="relevant_to_manuscript" checked><i></i>Manuscript relevance</label></fieldset>
<div class="hint">Drag nodes · scroll to zoom · drag background to pan</div>
<script>const DATA=__DATA__;
const canvas=document.querySelector('#graph'),ctx=canvas.getContext('2d'),panel=document.querySelector('#panel'),search=document.querySelector('#search'),focus=document.querySelector('#focus'),tag=document.querySelector('#tag');
const colors={cites:'#ffac62',bibliographic_coupling:'#55bde8',similar:'#65758d',relevant_to_manuscript:'#d583ff'},nodes=new Map(DATA.nodes.map(n=>[n.id,n]));
let W,H,dpr,scale=1,tx=0,ty=0,selected=nodes.get(DATA.origin),hover,drag,pan,last,active=new Set(Object.keys(colors)),running=true,reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
const hash=s=>[...s].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7),year=n=>n.year||new Date().getFullYear(),years=DATA.nodes.filter(n=>n.year).map(n=>n.year),minY=years.length?Math.min(...years):2000,maxY=years.length?Math.max(...years):2000;
DATA.nodes.forEach((n,i)=>{const a=i/Math.max(DATA.nodes.length,1)*Math.PI*2,j=(hash(n.id)%100)/100;n.x=Math.cos(a)*(180+j*90);n.y=Math.sin(a)*(180+j*90);n.vx=n.vy=0;n.r=n.kind==='manuscript'?18:Math.min(23,7+Math.log1p(n.citation_count||n.corpus_citation_count||0)*1.35)});
const edges=DATA.edges.map(e=>({...e,a:nodes.get(e.source),b:nodes.get(e.target)})).filter(e=>e.a&&e.b);[...nodes.values()].sort((a,b)=>a.kind.localeCompare(b.kind)||a.title.localeCompare(b.title)).forEach(n=>focus.add(new Option(`${n.kind==='manuscript'?'Manuscript':'Paper'} · ${n.title}`,n.id)));[...new Set(DATA.nodes.flatMap(n=>[...(n.tags||[]),...(n.topics||[])]))].sort().forEach(t=>tag.add(new Option(t.replaceAll('_',' '),t)));
function nodeVisible(n){const t=tag.value;return !t||(n.tags||[]).includes(t)||(n.topics||[]).includes(t)}function visibleNodes(){return DATA.nodes.filter(nodeVisible)}
function resize(){dpr=devicePixelRatio||1;W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function nodeColor(n){if(n.kind==='manuscript')return '#d583ff';const t=(year(n)-minY)/Math.max(1,maxY-minY);return `hsl(${215-t*175} 78% 62%)`}
function visibleEdges(){return edges.filter(e=>active.has(e.kind)&&nodeVisible(e.a)&&nodeVisible(e.b))}
function step(){const es=visibleEdges(),ns=visibleNodes();for(const n of ns){n.vx+=-n.x*.0007;n.vy+=-n.y*.0007}for(let i=0;i<ns.length;i++)for(let j=i+1;j<ns.length;j++){const a=ns[i],b=ns[j],dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy+80,f=55/d2;a.vx+=dx*f;a.vy+=dy*f;b.vx-=dx*f;b.vy-=dy*f}for(const e of es){const dx=e.b.x-e.a.x,dy=e.b.y-e.a.y,d=Math.hypot(dx,dy)||1,target=e.kind==='relevant_to_manuscript'?150:e.kind==='cites'?115:95,f=(d-target)*.0018;e.a.vx+=dx/d*f;e.a.vy+=dy/d*f;e.b.vx-=dx/d*f;e.b.vy-=dy/d*f}for(const n of ns){if(n===drag)continue;n.vx*=.9;n.vy*=.9;n.x+=n.vx;n.y+=n.vy}}
function point(n){return{x:W/2+tx+n.x*scale,y:H/2+ty+n.y*scale}}
function connected(n){const s=new Set([n.id]);visibleEdges().forEach(e=>{if(e.source===n.id)s.add(e.target);if(e.target===n.id)s.add(e.source)});return s}
function draw(){ctx.clearRect(0,0,W,H);const es=visibleEdges(),near=selected?connected(selected):null;ctx.lineCap='round';for(const e of es){const a=point(e.a),b=point(e.b),dim=near&&!near.has(e.a.id)&&!near.has(e.b.id);ctx.globalAlpha=dim?.08:e.kind==='similar'?.23:.52;ctx.strokeStyle=colors[e.kind];ctx.lineWidth=(e.kind==='cites'?1.7:Math.max(.6,e.score*2.2))*Math.min(scale,1.4);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(e.kind==='cites'){const ang=Math.atan2(b.y-a.y,b.x-a.x),r=e.b.r*scale+3,x=b.x-Math.cos(ang)*r,y=b.y-Math.sin(ang)*r;ctx.fillStyle=colors.cites;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-Math.cos(ang-.55)*8,y-Math.sin(ang-.55)*8);ctx.lineTo(x-Math.cos(ang+.55)*8,y-Math.sin(ang+.55)*8);ctx.fill()}}for(const n of visibleNodes()){const p=point(n),dim=near&&!near.has(n.id),isFocus=n===selected||n===hover;ctx.globalAlpha=dim?.16:1;ctx.fillStyle=nodeColor(n);ctx.beginPath();n.kind==='manuscript'?ctx.roundRect(p.x-n.r*scale,p.y-n.r*scale,n.r*2*scale,n.r*2*scale,5):ctx.arc(p.x,p.y,n.r*scale,0,Math.PI*2);ctx.fill();if(isFocus||n.id===DATA.origin){ctx.strokeStyle=n.id===DATA.origin?'#fff':'#77e0c2';ctx.lineWidth=2;ctx.stroke()}if(isFocus||scale>1.35){ctx.globalAlpha=1;ctx.fillStyle='#eaf2ff';ctx.font=`${isFocus?600:500} 12px Inter,system-ui`;ctx.textAlign='center';ctx.fillText(n.title.length>44?n.title.slice(0,43)+'…':n.title,p.x,p.y+n.r*scale+17)}}ctx.globalAlpha=1}
function frame(){if(running){step();draw();requestAnimationFrame(frame)}}
function hit(x,y){return [...visibleNodes()].reverse().find(n=>{const p=point(n);return Math.hypot(x-p.x,y-p.y)<n.r*scale+7})}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function relationLabel(k){return({cites:'citation',bibliographic_coupling:'shared references',similar:'topic similarity',relevant_to_manuscript:'manuscript relevance'})[k]||k}
function show(n){selected=n;focus.value=n.id;const allRel=visibleEdges().filter(e=>e.source===n.id||e.target===n.id).sort((a,b)=>(b.kind==='cites')-(a.kind==='cites')||b.score-a.score),rel=allRel.slice(0,18),hasGlobal=n.citation_count!=null;const tags=(n.tags||[]).map(t=>`<button class="chip" data-tag="${esc(t)}">${esc(t.replaceAll('_',' '))}</button>`).join('');const link=/^https:\/\//.test(n.url||'')?`<a class="source" href="${esc(n.url)}" target="_blank" rel="noreferrer">Open source ↗</a>`:'';panel.innerHTML=`<div class="eyebrow">${esc(n.kind)} · ${esc(n.tier||'group work')}</div><h1>${esc(n.title)}</h1><div class="sub">${esc(n.year||'Year unavailable')}</div><div class="metrics"><div class="metric"><b>${hasGlobal?n.citation_count:n.corpus_citation_count??'—'}</b><span>${hasGlobal?'Global cites':'Corpus cites'}</span></div><div class="metric"><b>${n.reference_count??'—'}</b><span>Resolved refs</span></div><div class="metric"><b>${allRel.length}</b><span>Links</span></div></div><div class="chips">${tags||'<span class="meta">No controlled tags</span>'}</div>${link}<div class="eyebrow">Connected in this view</div><div class="related">${rel.map(e=>{const other=e.source===n.id?e.b:e.a,label=e.kind==='cites'?(e.source===n.id?'cites':'cited by'):relationLabel(e.kind);return `<button data-id="${esc(other.id)}">${esc(other.title)}<small>${label} · ${e.score.toFixed(2)}${e.shared_references?` · ${e.shared_references} shared`:''}</small></button>`}).join('')||'<p class="empty">No visible relationships.</p>'}</div>`;panel.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>show(nodes.get(b.dataset.id)));panel.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{tag.value=b.dataset.tag;applyFilter()});draw()}
function fit(){const ns=visibleNodes();if(!ns.length)return;const xs=ns.map(n=>n.x),ys=ns.map(n=>n.y),span=Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys),200);scale=Math.min(1.6,Math.min(W-(W>820?390:30),H-160)/span*.82);tx=ty=0;draw()}
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);last={x:e.clientX,y:e.clientY};drag=hit(e.clientX,e.clientY);pan=!drag;if(drag)show(drag)};canvas.onpointermove=e=>{hover=hit(e.clientX,e.clientY);canvas.style.cursor=hover?'grab':pan?'grabbing':'default';if(!last)return;const dx=e.clientX-last.x,dy=e.clientY-last.y;if(drag){drag.x+=dx/scale;drag.y+=dy/scale;drag.vx=drag.vy=0}else if(pan){tx+=dx;ty+=dy}last={x:e.clientX,y:e.clientY};draw()};canvas.onpointerup=()=>{drag=pan=last=null};canvas.onwheel=e=>{e.preventDefault();const old=scale;scale=Math.max(.25,Math.min(4,scale*Math.exp(-e.deltaY*.001)));tx=e.clientX-W/2-(e.clientX-W/2-tx)*scale/old;ty=e.clientY-H/2-(e.clientY-H/2-ty)*scale/old;draw()};
function updateCount(){document.querySelector('#count').textContent=`${visibleNodes().length} works · ${visibleEdges().length} relationships`}function applyFilter(){if(!selected||!nodeVisible(selected))selected=visibleNodes()[0];selected?show(selected):panel.innerHTML='<p class="empty">No works match this tag.</p>';updateCount();fit()}
search.oninput=()=>{const q=search.value.toLowerCase().trim();hover=q?visibleNodes().find(n=>n.title.toLowerCase().includes(q)||n.id.toLowerCase().includes(q)):null;draw()};search.onkeydown=e=>{if(e.key==='Enter'&&hover)show(hover)};focus.onchange=()=>{if(focus.value){const n=nodes.get(focus.value);if(!nodeVisible(n))tag.value='';show(n);updateCount();fit()}};tag.onchange=applyFilter;document.querySelector('#fit').onclick=fit;document.querySelector('#reset').onclick=()=>{tag.value='';show(nodes.get(DATA.origin));updateCount();fit()};document.querySelector('#reload').onclick=()=>location.reload();document.querySelectorAll('.key input').forEach(c=>c.onchange=()=>{c.checked?active.add(c.value):active.delete(c.value);if(selected)show(selected);updateCount()});
updateCount();addEventListener('resize',resize);resize();show(selected);if(reduce){for(let i=0;i<300;i++)step();running=false;fit()}else{setTimeout(()=>{running=false;fit()},2600);requestAnimationFrame(frame)}
</script></body></html>"""
        .replace("__TITLE__", html.escape(origin["title"]))
        .replace("__DATA__", payload)
    )
